const PracticalLearning=lazy(()=>import('../components/PracticalLearning'));
const RobotTestWorkbench=lazy(()=>import('../components/RobotTestWorkbench'));
const RobotLearningLab=lazy(()=>import('../components/RobotLearningLab'));
type Course = { id:string; title:string; description:string; domain:string; target_subteam:string|null; required:boolean; active:boolean; sort_order:number };
type Module = { id:string; course_id:string; title:string; instructions:string; sort_order:number };
type Enrollment = { id:string; course_id:string; member_id:string; status:string; due_at:string|null };
type Evidence = { id:string; enrollment_id:string; module_id:string; member_id:string; note:string; status:string; review_note:string|null };
type QuizQuestion={id:string;prompt:any;kind:"single_choice"|"multiple_choice"|"written";options:string[];correct_answers:string[];points:number};
type PublicQuizQuestion=Omit<QuizQuestion,"correct_answers">;
type Assessment = { id:string; course_id:string; module_id:string|null; title:string; instructions:string; assessment_type:"assignment"|"quiz"|"practical"|"reflection"; questions:(string|PublicQuizQuestion)[]; required:boolean; graded:boolean; max_score:number|null; passing_score:number|null; due_at:string|null; max_attempts:number; target_type:"all"|"subteams"|"members"; target_values:string[]; sort_order:number; active:boolean };
type AssessmentSubmission = { id:string; assessment_id:string; enrollment_id:string; member_id:string; response:string; answers:Record<string,string|string[]>; resource_url:string|null; status:"draft"|"submitted"|"reviewed"|"changes_requested"; score:number|null; feedback:string|null; submitted_at:string|null; attempt_number:number };
type ProgressEvent = { id:string; enrollment_id:string; assessment_id:string|null; submission_id:string|null; member_id:string; event_type:string; from_status:string|null; to_status:string|null; score:number|null; attempt_number:number|null; details:string|null; created_at:string };
type Person = { id:string; display_name:string; subteam:string|null; subteams:string[] };
type CourseForm = { title:string; description:string; domain:string; target_subteam:string; required:boolean };
const blank:CourseForm={title:"",description:"",domain:"mechanical",target_subteam:"",required:true};
const domains=["mechanical","electrical","software","cad","strategy","drive_pit","business","safety"];

function LinkedText({text}:{text:string}) {
  return <p>{text.split(/(https?:\/\/[^\s)\]}>,;]+)/g).map((part,index)=>part.startsWith("http")
    ? <a className="training-resource-link" href={part} target="_blank" rel="noreferrer" key={`${part}-${index}`}>{part.replace(/^https?:\/\//,"")} ↗</a>
    : part)}</p>;
}

export default function TrainingCenterPage(){
  const {pick,language}=useLocalization();
  const label=(value:string)=>academyLabel(value,pick);
  const text=(value:string|null|undefined)=>academyText(value,pick);
  const {profile}=useMemberAuth();
  const navigation=useAcademyNavigation();const searchParams=navigation.params;
  const access=useAccessControl();
  const canCreate=access.can("manage_training")||(profile?.leader_subteams??[]).some(team=>access.can("manage_training",team));
  const canReview=access.can("validate_training");
  const canDelete=profile?.role==="admin";
  const isAdmin=profile?.role==="admin";
  const [officialCatalog,setOfficialCatalog]=useState<OfficialCourse[]>([]);
  const [officialCredits,setOfficialCredits]=useState<{member_id:string;assessment_id:string;certificate_id:string}[]>([]);
  const [officialPending,setOfficialPending]=useState(0);
  const [rawCourses,setCourses]=useState<Course[]>([]);
  const courses=rawCourses.map(c=>({...c,title:text(c.title),description:text(c.description)}));
  const {instructor,setInstructor}=navigation;
  const [studentPreview,setStudentPreview]=useState(false);
  const canReorder=isAdmin&&instructor&&!studentPreview;
  const [reviewCourse,setReviewCourse]=useState("");
  const {step:practicalStep,setStep:setPracticalStep}=navigation;
  const [reviewSubmission,setReviewSubmission]=useState<string|undefined>();
  const {labCourse,setLabCourse}=navigation;
  const [loading,setLoading]=useState(true);
  const [modules,setModules]=useState<Module[]>([]);
  const [enrollments,setEnrollments]=useState<Enrollment[]>([]);
  const [evidence,setEvidence]=useState<Evidence[]>([]);
  const [assessments,setAssessments]=useState<Assessment[]>([]);
  const [assessmentSubmissions,setAssessmentSubmissions]=useState<AssessmentSubmission[]>([]);
  const [progressEvents,setProgressEvents]=useState<ProgressEvent[]>([]);
  const [people,setPeople]=useState<Person[]>([]);
  const {course:selected,setCourse:setSelected}=navigation;
  const [message,setMessage]=useState("");
  const [formMode,setFormMode]=useState<"closed"|"create"|"edit">("closed");
  const [course,setCourse]=useState<CourseForm>(blank);
  const [moduleTitle,setModuleTitle]=useState("");
  const [instructions,setInstructions]=useState("");
  const [editingModule,setEditingModule]=useState<string|null>(null);
  const [assignmentMode,setAssignmentMode]=useState<"all"|"subteam"|"members">("members");
  const [assignSubteam,setAssignSubteam]=useState("");
  const [assignMembers,setAssignMembers]=useState<string[]>([]);
  const [assignDue,setAssignDue]=useState("");
  const [note,setNote]=useState<Record<string,string>>({});
  const [draggedCourse,setDraggedCourse]=useState<string|null>(null);
  const requestedView=searchParams.get("view");
  const {view:academyView,setView:setAcademyView}=navigation;
  const [assessmentForm,setAssessmentForm]=useState({title:"",instructions:"",assessment_type:"assignment" as Assessment["assessment_type"],questions:"",required:true,graded:false,max_score:"",passing_score:"",due_at:"",max_attempts:"1",target_type:"all" as Assessment["target_type"],target_values:[] as string[]});
  const newQuizQuestion=():QuizQuestion=>({id:crypto.randomUUID(),prompt:"",kind:"single_choice",options:["","","",""],correct_answers:[],points:1});
  const [quizQuestions,setQuizQuestions]=useState<QuizQuestion[]>([newQuizQuestion()]);
  const [answerKeys,setAnswerKeys]=useState<Record<string,Record<string,string[]>>>({});
  const [editingAssessment,setEditingAssessment]=useState<string|null>(null);
  const [submissionDrafts,setSubmissionDrafts]=useState<Record<string,{response:string;resource_url:string;answers:Record<string,string|string[]>}>>({});

  async function load(){
    await supabase.rpc("refresh_my_training_reminders");
    const [c,m,e,v,p,a,s,k,h,oc,cr,cp]=await Promise.all([
      supabase.from("training_courses").select("*").eq("active",true).order("sort_order").order("created_at"),
      supabase.from("training_modules").select("*").order("sort_order"),
      supabase.from("training_enrollments").select("*"),
      supabase.from("training_evidence").select("*"),
      supabase.from("team_members").select("id,display_name,subteam,subteams").eq("active",true),
      supabase.from("training_assessments").select("*").eq("active",true).order("sort_order"),
      supabase.from("training_assessment_submissions").select("*").order("updated_at",{ascending:false}),
      supabase.from("training_assessment_answer_keys").select("assessment_id,answers"),
      supabase.from("training_progress_events").select("*").order("created_at",{ascending:false}).limit(500),
      supabase.from('training_official_catalog').select('*').order('course_id'),
      supabase.from('training_official_credits').select('*'),
      supabase.from('training_certificates').select('id').eq('status','submitted')
    ]);
    const next=(c.data??[]) as Course[];
    setLoading(false);
    const failure=[c,m,e,v,p,a,s,k,h,oc,cr,cp].find(result=>result.error);if(failure?.error)setMessage(failure.error.message);
    setOfficialCatalog(oc.data??[]);setOfficialCredits(cr.data??[]);setOfficialPending(cp.data?.length??0);
    setCourses(next); setModules((m.data??[]) as Module[]); setEnrollments((e.data??[]) as Enrollment[]); setEvidence((v.data??[]) as Evidence[]); setPeople((p.data??[]) as Person[]);
    if(!a.error)setAssessments((a.data??[]) as Assessment[]); if(!s.error)setAssessmentSubmissions((s.data??[]) as AssessmentSubmission[]);if(!k.error)setAnswerKeys(Object.fromEntries((k.data??[]).map(row=>[row.assessment_id,row.answers])));if(!h.error)setProgressEvents((h.data??[]) as ProgressEvent[]);
    if(!selected&&next[0]) setSelected(next.find(x=>x.id===searchParams.get("course"))?.id??(requestedView==="practical"?next.find(x=>x.id.startsWith("67402026-1002-"))?.id:undefined)??next[0].id);
    else if(selected&&!next.some(x=>x.id===selected)) setSelected(next[0]?.id??"");
  }
  useEffect(()=>{void load();},[]);

  async function saveCourse(e:FormEvent){
    e.preventDefault();
    if(!access.can("manage_training",course.target_subteam||null)){setMessage(pick("Choose a department you are authorized to lead.","בחרו מחלקה שאתם מורשים להוביל."));return;}
    const payload={...course,target_subteam:course.target_subteam||null};
    const result=formMode==="edit"
      ? await supabase.from("training_courses").update(payload).eq("id",selected)
      : await supabase.from("training_courses").insert({...payload,created_by:profile?.id}).select("id").single();
    setMessage(result.error?.message??pick(formMode==="edit"?"Course updated.":"Course created.",formMode==="edit"?"הקורס עודכן.":"הקורס נוצר."));
    if(!result.error){if(formMode==="create"&&result.data?.id)setSelected(result.data.id);setFormMode("closed");setCourse(blank);await load();}
  }
  function editCourse(item:Course){item=rawCourses.find(c=>c.id===item.id)??item;setCourse({title:item.title,description:item.description,domain:item.domain,target_subteam:item.target_subteam??"",required:item.required});setFormMode("edit");window.scrollTo({top:0,behavior:"smooth"});}
  async function archiveCourse(item:Course){if(!confirm(pick(`Archive “${item.title}”? Student evidence will be preserved.`,`להעביר את „${item.title}” לארכיון? ראיות תלמידים יישמרו.`)))return;const {error}=await supabase.from("training_courses").update({active:false}).eq("id",item.id);setMessage(error?.message??pick("Course archived.","הקורס הועבר לארכיון."));if(!error)await load();}
  async function deleteCourse(item:Course){if(!confirm(pick(`Permanently delete “${item.title}” and all related evidence?`,`למחוק לצמיתות את „${item.title}” ואת כל הראיות הקשורות?`)))return;const {error}=await supabase.from("training_courses").delete().eq("id",item.id);setMessage(error?.message??pick("Course deleted.","הקורס נמחק."));if(!error)await load();}
  async function reorderCourse(sourceId:string,targetId:string){if(!canReorder||sourceId===targetId)return;const sourceIndex=courses.findIndex(item=>item.id===sourceId),targetIndex=courses.findIndex(item=>item.id===targetId);if(sourceIndex<0||targetIndex<0)return;const ordered=[...rawCourses],[moved]=ordered.splice(sourceIndex,1);ordered.splice(targetIndex,0,moved);setCourses(ordered);const results=await Promise.all(ordered.map((item,index)=>supabase.from("training_courses").update({sort_order:(index+1)*10}).eq("id",item.id)));const error=results.find(result=>result.error)?.error;setMessage(error?.message??pick("Course priority updated.","סדר העדיפות של הקורסים עודכן."));if(error)await load();}
  function moveCourse(id:string,direction:-1|1){const index=courses.findIndex(item=>item.id===id),target=courses[index+direction];if(target)void reorderCourse(id,target.id);}
  async function saveModule(e:FormEvent){e.preventDefault();const current=modules.find(x=>x.id===editingModule);const payload={course_id:selected,title:moduleTitle,instructions,sort_order:current?.sort_order??modules.filter(x=>x.course_id===selected).length*10+10};const result=editingModule?await supabase.from("training_modules").update(payload).eq("id",editingModule):await supabase.from("training_modules").insert(payload);setMessage(result.error?.message??pick(editingModule?"Module updated.":"Module added.",editingModule?"היחידה עודכנה.":"היחידה נוספה."));if(!result.error){setEditingModule(null);setModuleTitle("");setInstructions("");await load();}}
  async function deleteModule(item:Module){if(!confirm(pick(`Delete module “${item.title}”?`,`למחוק את היחידה „${item.title}”?`)))return;const {error}=await supabase.from("training_modules").delete().eq("id",item.id);setMessage(error?.message??pick("Module deleted.","היחידה נמחקה."));if(!error)await load();}
  function toggleMember(id:string){setAssignMembers(current=>current.includes(id)?current.filter(x=>x!==id):[...current,id]);}
  async function enroll(){const ids=assignmentMode==="all"?people.map(x=>x.id):assignmentMode==="subteam"?people.filter(x=>memberTeams(x).some(team=>normalizedTeamMatch(team,assignSubteam))).map(x=>x.id):assignMembers;if(!selected||!ids.length){setMessage(pick("Choose at least one member or subteam.","בחרו לפחות חבר/ה או תת־צוות."));return;}const {data,error}=await supabase.from("training_enrollments").upsert(ids.map(member_id=>({course_id:selected,member_id,assigned_by:profile?.id,due_at:assignDue||null})),{onConflict:"course_id,member_id"}).select("id");setMessage(error?.message??pick(`Course assigned to ${ids.length} members.`,`הקורס הוקצה ל־${ids.length} חברים.`));if(!error){void Promise.all((data??[]).map(item=>notifyActionSource("training_enrollments",item.id)));setAssignMembers([]);await load();}}
  async function submit(enrollment:Enrollment,module:Module){if(studentPreview||!profile||!note[module.id]?.trim())return;const {error}=await supabase.from("training_evidence").upsert({enrollment_id:enrollment.id,module_id:module.id,member_id:profile.id,note:note[module.id].trim(),status:"submitted"},{onConflict:"enrollment_id,module_id"});if(!error){await supabase.from("training_enrollments").update({status:"in_progress"}).eq("id",enrollment.id);setNote({...note,[module.id]:""});await load();}setMessage(error?.message??pick("Evidence submitted.","הראיה נשלחה."));}
  async function review(item:Evidence,status:"approved"|"changes_requested"){const review_note=prompt(pick("Mentor review note","הערת חונך"));const {error}=await supabase.from("training_evidence").update({status,review_note:review_note||null,reviewed_by:profile?.id,reviewed_at:new Date().toISOString()}).eq("id",item.id);setMessage(error?.message??pick("Review saved.","הבדיקה נשמרה."));if(!error)await load();}

  function resetAssessmentForm(){setAssessmentForm({title:"",instructions:"",assessment_type:"assignment",questions:"",required:true,graded:false,max_score:"",passing_score:"",due_at:"",max_attempts:"1",target_type:"all",target_values:[]});setQuizQuestions([newQuizQuestion()]);setEditingAssessment(null);}
  function patchQuizQuestion(index:number,patch:Partial<QuizQuestion>){setQuizQuestions(current=>current.map((item,itemIndex)=>itemIndex===index?{...item,...patch}:item));}
  function addQuizQuestion(){setQuizQuestions(current=>[...current,newQuizQuestion()]);}
  function toggleCorrectAnswer(index:number,answer:string){setQuizQuestions(current=>current.map((item,itemIndex)=>{if(itemIndex!==index)return item;const selected=item.correct_answers.includes(answer);return{...item,correct_answers:item.kind==="single_choice"?[answer]:selected?item.correct_answers.filter(value=>value!==answer):[...item.correct_answers,answer]};}));}
  async function saveAssessment(e:FormEvent){
    e.preventDefault();
    const cleanQuiz=quizQuestions.map(item=>({...item,prompt:item.prompt.trim(),options:item.kind!=="written"?item.options.map(value=>value.trim()).filter(Boolean):[],correct_answers:item.correct_answers.filter(Boolean),points:Math.max(1,Number(item.points)||1)})).filter(item=>item.prompt);
    const questions=assessmentForm.assessment_type==="quiz"?cleanQuiz.map(({correct_answers:_,...question})=>question):(assessmentForm.questions.split("\n").map(value=>value.trim()).filter(Boolean));
    if(assessmentForm.assessment_type==="quiz"&&!questions.length){setMessage(pick("Add at least one quiz question.","יש להוסיף לפחות שאלת מבחן אחת."));return;}
    if(assessmentForm.assessment_type==="quiz"&&cleanQuiz.some(item=>item.kind!=="written"&&!item.correct_answers.length)){setMessage(pick("Mark the correct answer for every choice question.","יש לסמן תשובה נכונה לכל שאלת בחירה."));return;}
    const calculatedMax=assessmentForm.assessment_type==="quiz"?cleanQuiz.reduce((sum,item)=>sum+item.points,0):Number(assessmentForm.max_score)||null;
    if(assessmentForm.target_type!=="all"&&!assessmentForm.target_values.length){setMessage(pick("Choose at least one team or member.","יש לבחור לפחות צוות או חבר/ה."));return;}
    const payload={course_id:selected,title:assessmentForm.title.trim(),instructions:assessmentForm.instructions.trim(),assessment_type:assessmentForm.assessment_type,questions,required:assessmentForm.required,graded:assessmentForm.graded,max_score:assessmentForm.graded?calculatedMax:null,passing_score:assessmentForm.graded&&assessmentForm.passing_score?Number(assessmentForm.passing_score):null,due_at:assessmentForm.due_at?new Date(assessmentForm.due_at).toISOString():null,max_attempts:Math.max(1,Number(assessmentForm.max_attempts)||1),target_type:assessmentForm.target_type,target_values:assessmentForm.target_values,updated_at:new Date().toISOString()};
    const result=editingAssessment?await supabase.from("training_assessments").update(payload).eq("id",editingAssessment).select("id").single():await supabase.from("training_assessments").insert({...payload,created_by:profile?.id,sort_order:assessments.filter(item=>item.course_id===selected).length*10+10}).select("id").single();
    if(!result.error&&result.data?.id&&assessmentForm.assessment_type==="quiz"){const key=Object.fromEntries(cleanQuiz.map(item=>[item.id,item.correct_answers]));const keyResult=await supabase.from("training_assessment_answer_keys").upsert({assessment_id:result.data.id,answers:key,updated_by:profile?.id,updated_at:new Date().toISOString()});if(keyResult.error){setMessage(keyResult.error.message);return;}}
    if(!result.error&&result.data?.id&&assessmentForm.required){const {data:assigned}=await supabase.from("training_assessment_assignments").select("id").eq("assessment_id",result.data.id);void Promise.all((assigned??[]).map(row=>notifyActionSource("training_assessment_assignments",row.id)));}
    setMessage(result.error?.message??pick(editingAssessment?"Assessment updated.":"Assessment created.",editingAssessment?"המטלה עודכנה.":"המטלה נוצרה."));
    if(!result.error){resetAssessmentForm();await load();}
  }
  function editAssessment(item:Assessment){const key=answerKeys[item.id]??{},structured=(item.questions??[]).filter(question=>typeof question!=="string").map((question,index)=>{const legacy=question as PublicQuizQuestion&{correct_answer?:string},id=question.id??`legacy-${index+1}`,kind=question.kind==="written"||question.kind==="multiple_choice"||question.kind==="single_choice"?question.kind:(question.kind as string)==="free_text"?"written":"single_choice";return{...question,id,kind,correct_answers:key[id]??(legacy.correct_answer?[legacy.correct_answer]:[])};}) as QuizQuestion[];setAssessmentForm({title:item.title,instructions:item.instructions,assessment_type:item.assessment_type,questions:(item.questions??[]).filter(question=>typeof question==="string").join("\n"),required:item.required,graded:item.graded,max_score:item.max_score?.toString()??"",passing_score:item.passing_score?.toString()??"",due_at:item.due_at?new Date(item.due_at).toISOString().slice(0,16):"",max_attempts:String(item.max_attempts??1),target_type:item.target_type??"all",target_values:item.target_values??[]});setQuizQuestions(structured.length?structured:[newQuizQuestion()]);setEditingAssessment(item.id);setAcademyView("assessments");}
  async function archiveAssessment(item:Assessment){const {error}=await supabase.from("training_assessments").update({active:false,updated_at:new Date().toISOString()}).eq("id",item.id);setMessage(error?.message??pick("Assessment archived.","המטלה הועברה לארכיון."));if(!error)await load();}
  function draftFor(item:Assessment){const existing=assessmentSubmissions.find(row=>row.assessment_id===item.id&&row.member_id===profile?.id);return submissionDrafts[item.id]??{response:existing?.response??"",resource_url:existing?.resource_url??"",answers:existing?.answers??{}};}
  async function submitAssessment(item:Assessment){
    if(studentPreview||!profile||!myEnrollment)return;
    const draft=draftFor(item),hasAnswers=!item.questions?.length||item.questions.every(question=>{const key=typeof question==="string"?String(item.questions.indexOf(question)):question.id,value=draft.answers[key];return Array.isArray(value)?value.length>0:Boolean(value?.trim());});
    if(!draft.response.trim()&&!draft.resource_url.trim()&&!item.questions?.length){setMessage(pick("Add your answer or an evidence link before submitting.","יש להוסיף תשובה או קישור לראיה לפני ההגשה."));return;}
    if(!hasAnswers){setMessage(pick("Answer every test question before submitting.","יש לענות על כל שאלות המבחן לפני ההגשה."));return;}
    const result=item.assessment_type==="quiz"
      ? await supabase.rpc("submit_training_quiz",{target_assessment:item.id,target_enrollment:myEnrollment.id,submitted_answers:draft.answers,submitted_response:draft.response.trim(),submitted_resource_url:draft.resource_url.trim()||null})
      : await supabase.from("training_assessment_submissions").insert({assessment_id:item.id,enrollment_id:myEnrollment.id,member_id:profile.id,response:draft.response.trim(),resource_url:draft.resource_url.trim()||null,answers:draft.answers,status:"submitted",submitted_at:new Date().toISOString(),attempt_number:(assessmentSubmissions.filter(row=>row.assessment_id===item.id&&row.enrollment_id===myEnrollment.id).length+1)});
    const {error}=result;
    setMessage(error?.message??pick("Work submitted for review.","העבודה נשלחה לבדיקה."));if(!error)await load();
  }
  async function reviewAssessment(item:AssessmentSubmission,status:"reviewed"|"changes_requested"){
    if(item.assessment_id.startsWith("67402026-1002-")){const a=assessments.find(a=>a.id===item.assessment_id);if(a)setSelected(a.course_id);setPracticalStep(3);setReviewSubmission(item.id);setAcademyView("practical");setMessage("");return;}
    const assessment=assessments.find(row=>row.id===item.assessment_id),feedback=prompt(pick("Feedback for the student","משוב לתלמיד/ה"),item.feedback??"");if(feedback===null)return;
    const scoreText=assessment?.graded&&status==="reviewed"?prompt(pick(`Score out of ${assessment.max_score}`,`ציון מתוך ${assessment.max_score}`),item.score?.toString()??""):null;
    const score=scoreText?.trim()?Number(scoreText):null;
    if(score!==null&&(!Number.isFinite(score)||score<0||(assessment?.max_score!=null&&score>assessment.max_score))){setMessage(pick("Enter a valid score within the assessment range.","יש להזין ציון תקין בטווח המטלה."));return;}
    const {error}=await supabase.from("training_assessment_submissions").update({status,feedback:feedback.trim()||null,score,reviewed_by:profile?.id,reviewed_at:new Date().toISOString(),updated_at:new Date().toISOString()}).eq("id",item.id);
    setMessage(error?.message??pick(status==="reviewed"?"Assessment reviewed.":"Changes requested.",status==="reviewed"?"המטלה נבדקה.":"נשלחה בקשת תיקון."));if(!error)await load();
  }

  const active=courses.find(x=>x.id===selected);
  const isOfficial=officialCatalog.some(c=>c.course_id===selected);
  const canEdit=instructor&&!studentPreview&&access.can("manage_training",active?.target_subteam);
  const courseModules=modules.filter(x=>x.course_id===selected);
  const myEnrollment=enrollments.find(x=>x.course_id===selected&&x.member_id===profile?.id);
  const courseAssessments=assessments.filter(x=>x.course_id===selected);
  const reviewQueue=assessmentSubmissions.filter(x=>(!reviewCourse||assessments.some(a=>a.id===x.assessment_id&&a.course_id===reviewCourse))&&x.status==="submitted");
  const moduleReviewQueue=evidence.filter(x=>x.status==="submitted"&&(!reviewCourse||modules.some(m=>m.id===x.module_id&&m.course_id===reviewCourse)));
  const pendingCount=officialPending+assessmentSubmissions.filter(x=>x.status==="submitted").length+evidence.filter(x=>x.status==="submitted").length;
  function openCourse(id:string,feedback=false,step?:number){setSelected(id);setPracticalStep(feedback?3:step);setReviewSubmission(undefined);setAcademyView(id.startsWith("67402026-1002-")?"practical":feedback&&!officialCatalog.some(c=>c.course_id===id)?"assessments":"content");}
  function enterInstructor(){setInstructor(true);setStudentPreview(false);setAcademyView(canCreate?"content":"review");void load();}
  function leaveInstructor(view:"home"|"explore"|"progress"){setInstructor(false);setStudentPreview(false);setFormMode("closed");setAcademyView(view);void load();}
  const publicAssessments=assessments.map(a=>({...a,title:text(a.title),instructions:text(a.instructions)}));
  const learningEnrollments=enrollments.map(e=>({...e,official_training:officialCatalog.some(c=>c.course_id===e.course_id)}));
  const officialProps={pick,memberId:profile?.id,catalog:officialCatalog,canReview:instructor&&canReview,canAssign:instructor&&!studentPreview&&canCreate,assignableMemberIds:people.filter(p=>access.can("manage_training")||memberTeams(p).some(team=>access.can("manage_training",team))).map(p=>p.id),people,open:(id:string)=>openCourse(id),onChange:()=>void load(),previewOnly:studentPreview};
  const quizTotal=quizQuestions.reduce((sum,item)=>sum+(Number(item.points)||0),0);
  const buildReturn=buildLearningReturn(searchParams.get("return"));
  return <main className="hub-page training-center-page">
    {buildReturn&&<div className="academy-context-bar"><Link to={buildReturn}>{pick("Return to workshop job","חזרה לעבודת הסדנה")}</Link><span>{pick("Your existing learning and verified certificates are reused.","הלמידה והתעודות המאומתות הקיימות שלך נשמרות לשימוש חוזר.")}</span></div>}
    <header className="training-hero academy-compact-hero"><div><div className="hub-eyebrow">FRC 6740 · {pick("Structured qualification","הסמכה מובנית")}</div><h1>{pick("Skills Academy","אקדמיית מיומנויות")}</h1><p>{pick("Your next step, your feedback and your progress — in one place.","הצעד הבא, המשוב וההתקדמות שלך — במקום אחד.")}</p></div>{instructor&&canCreate&&!studentPreview?<button onClick={()=>{setAcademyView("content");setCourse({...blank,target_subteam:profile?.role==="team_leader"?(profile.leader_subteams?.[0]??""):""});setFormMode(formMode==="create"?"closed":"create");}}>+ {pick("Create course","יצירת קורס")}</button>:null}</header>
    {message?<div className="hub-message" role="status">{message}</div>:null}
    <nav className="academy-primary-nav" aria-label={pick("Skills Academy sections","אזורי האקדמיה")}>
      <button aria-current={!instructor&&["home","content","assessments","practical"].includes(academyView)?"page":undefined} onClick={()=>leaveInstructor("home")}>{pick("My learning","הלמידה שלי")}</button>
      <button aria-current={!instructor&&["explore","catalog","robot-lab"].includes(academyView)?"page":undefined} onClick={()=>leaveInstructor("explore")}>{pick("Explore","לגלות ולחקור")}</button>
      <button aria-current={!instructor&&academyView==="progress"?"page":undefined} onClick={()=>leaveInstructor("progress")}>{pick("My progress","ההתקדמות שלי")}</button>
      {(canCreate||canReview)&&<button className="academy-instructor-entry" aria-current={instructor?"page":undefined} onClick={enterInstructor}>{pick("Instructor workspace","מרחב מדריכים")}</button>}
    </nav>
    {instructor&&(canCreate||canReview)&&<><h2>{pick("Instructor workspace","מרחב מדריכים")}</h2><nav className="academy-subnav" aria-label={pick("Instructor tools","כלי הדרכה")}>{canCreate&&<button aria-current={["content","assessments"].includes(academyView)?"page":undefined} onClick={()=>{setStudentPreview(false);setAcademyView("content");}}>{pick("Courses & assignments","קורסים והקצאות")}</button>}{canReview&&<><button aria-current={academyView==="review"?"page":undefined} onClick={()=>{setStudentPreview(false);setAcademyView("review");void load();}}>{pick("Review submissions","בדיקת הגשות")} · {pendingCount}</button><button aria-current={academyView==="progress"?"page":undefined} onClick={()=>{setStudentPreview(false);setAcademyView("progress");}}>{pick("Team progress","התקדמות הקבוצה")}</button></>}</nav></>}
    {instructor&&canCreate&&officialCatalog.length>0&&<button className="hub-button secondary" onClick={()=>{setStudentPreview(false);setFormMode("closed");openCourse(officialCatalog[0].course_id);}}>{pick("Assign official FIRST training","הקצאת הכשרה רשמית של FIRST")}</button>}
    {loading&&<p role="status">{pick("Loading your learning…","טוען את הלמידה שלך…")}</p>}
    {academyView==="home"&&!loading&&<AcademyHome pick={pick} credits={officialCredits} memberId={profile?.id} courses={courses} enrollments={learningEnrollments} assessments={publicAssessments} submissions={assessmentSubmissions} modules={modules} evidence={evidence} open={openCourse} explore={()=>leaveInstructor("explore")}/>}
    {academyView==="explore"&&<><OfficialTraining {...officialProps} mode="explore"/><h2>{pick("Explore without an assignment","לחקור גם בלי מטלה")}</h2><div className="academy-explore-grid"><article className="academy-explore-card"><h3>{pick("Learning library","ספריית למידה")}</h3><p>{pick("Official guides and useful team references, organized by topic.","מדריכים רשמיים ומקורות קבוצתיים לפי נושא.")}</p><button onClick={()=>setAcademyView("catalog")}>{pick("Browse resources","עיון במקורות")}</button></article><article className="academy-explore-card"><h3>{pick("Robot learning lab","מעבדת רובוטים")}</h3><p>{pick("Inspect published real CAD and understand each subsystem.","בדקו מודלי CAD אמיתיים שפורסמו והכירו תתי־מערכות.")}</p><button onClick={()=>{setLabCourse("");setAcademyView("robot-lab");}}>{pick("Explore robots in 3D","חקירת רובוטים בתלת־ממד")}</button></article></div><h3>{pick("Available courses","קורסים זמינים")}</h3><div className="academy-course-rows">{courses.filter(c=>!officialCatalog.some(o=>o.course_id===c.id)).map(c=><article key={c.id}><div><h3>{c.title}</h3><p>{c.description}</p></div><button onClick={()=>openCourse(c.id)}>{pick("Explore course","עיון בקורס")}</button></article>)}</div></>}
    {["content","assessments","practical"].includes(academyView)&&active&&<div className="academy-context-bar"><strong>{active.title}</strong>{!isOfficial&&!selected.startsWith("67402026-1002-")&&<><button onClick={()=>setAcademyView("content")}>{pick("Lesson & references","שיעור ומקורות")}</button><button onClick={()=>setAcademyView("assessments")}>{instructor&&!studentPreview?pick("Build assessments","עריכת מטלות"):pick("Assignments & feedback","מטלות ומשוב")}</button></>}{canEdit&&<button onClick={()=>setAcademyView("catalog")}>{pick("Add reference","הוספת מקור")}</button>}{instructor&&<button onClick={()=>setStudentPreview(!studentPreview)}>{studentPreview?pick("Return to editing","חזרה לעריכה"):pick("Preview as learner","תצוגת לומד")}</button>}</div>}
    {canEdit&&!isOfficial&&active&&["content","practical"].includes(academyView)&&<CourseSourceReview courseId={selected} pick={pick}/>}
    {studentPreview&&<p className="academy-preview-note">{pick("Learner layout preview. Your identity and permissions do not change; no student is impersonated.","תצוגת מבנה ללומד. הזהות וההרשאות שלך אינן משתנות ואין התחזות לתלמיד.")}</p>}
    {academyView==="robot-lab"&&searchParams.get('return')?.startsWith('/knowledge?')&&<Link to={searchParams.get('return')!}>{pick('Return to research results','חזרה לתוצאות המחקר')}</Link>}
    {academyView==="robot-lab"&&labCourse&&<div className="academy-context-bar"><strong>{courses.find(c=>c.id===labCourse)?.title}</strong><button onClick={()=>openCourse(labCourse)}>{pick("Return to my course","חזרה לקורס שלי")}</button></div>}
    {academyView==="robot-tests"&&<div className="academy-context-bar"><Link to="/robot-reliability">{pick("Robot reliability & engineering","אמינות רובוט והנדסה")}</Link><button onClick={()=>leaveInstructor("home")}>{pick("Return to learning","חזרה ללמידה")}</button></div>}
    {instructor&&!studentPreview&&canCreate&&formMode!=="closed"?<form className="hub-card training-course-form" onSubmit={saveCourse}><div className="training-form-heading"><strong>{pick(formMode==="edit"?"Edit course":"New course",formMode==="edit"?"עריכת קורס":"קורס חדש")}</strong><button type="button" onClick={()=>setFormMode("closed")} aria-label={pick("Close","סגירה")}>×</button></div><label>{pick("Course title","שם הקורס")}<input required value={authorText(course.title,language)} onChange={e=>setCourse({...course,title:updateAuthorText(course.title,e.target.value,language)})}/></label><label>{pick("Domain","תחום")}<select value={course.domain} onChange={e=>setCourse({...course,domain:e.target.value})}>{domains.map(x=><option key={x} value={x}>{label(x)}</option>)}</select></label><label>{pick("Target subteam","תת־צוות יעד")}<input value={course.target_subteam} onChange={e=>setCourse({...course,target_subteam:e.target.value})}/></label><label className="wide">{pick("What members will learn","מה החברים ילמדו")}<textarea required rows={3} value={authorText(course.description,language)} onChange={e=>setCourse({...course,description:updateAuthorText(course.description,e.target.value,language)})}/></label><label className="checkbox-label"><input type="checkbox" checked={course.required} onChange={e=>setCourse({...course,required:e.target.checked})}/>{pick("Required course","קורס חובה")}</label><button className="hub-button">{pick(formMode==="edit"?"Save changes":"Create course",formMode==="edit"?"שמירת שינויים":"יצירת קורס")}</button></form>:null}
    {academyView==="content"&&isOfficial&&<><label className="official-course-picker">{pick("Choose a course","בחירת קורס")}<select value={selected} onChange={e=>setSelected(e.target.value)}>{courses.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><OfficialTraining {...officialProps} mode="detail" selected={selected}/></>}
    {academyView==="content"&&!isOfficial?<><label className="mobile-course-picker"><span>{pick("Choose a course","בחירת קורס")}</span><select value={selected} onChange={e=>{setSelected(e.target.value);setFormMode("closed");}}>{courses.map(item=><option value={item.id} key={item.id}>{item.title}</option>)}</select><small>{active?.domain?label(active.domain):null}{active?.required?` · ${pick("required","חובה")}`:""}</small></label><div className="training-layout"><aside className={canReorder?"course-priority-list is-sortable":"course-priority-list"}>{canReorder?<p className="course-order-hint">↕ {pick("Drag courses to set the order seen by the team","גררו קורסים כדי לקבוע את הסדר שיוצג לקבוצה")}</p>:null}{courses.map((x,index)=><div className={`${selected===x.id?"is-active":""}${draggedCourse===x.id?" is-dragging":""}`} draggable={canReorder} onDragStart={()=>setDraggedCourse(x.id)} onDragOver={event=>{if(canReorder)event.preventDefault();}} onDrop={()=>{if(draggedCourse)void reorderCourse(draggedCourse,x.id);setDraggedCourse(null);}} onDragEnd={()=>setDraggedCourse(null)} key={x.id}><button className="course-select-button" onClick={()=>{setSelected(x.id);setFormMode("closed");}}><strong>{x.title}</strong><small>{label(x.domain)}{x.required?` · ${pick("required","חובה")}`:""}</small></button>{canReorder?<span className="course-order-controls"><button type="button" disabled={index===0} onClick={()=>moveCourse(x.id,-1)} aria-label={pick(`Move ${x.title} up`,`${x.title} למעלה`)}>↑</button><button type="button" disabled={index===courses.length-1} onClick={()=>moveCourse(x.id,1)} aria-label={pick(`Move ${x.title} down`,`${x.title} למטה`)}>↓</button></span>:null}</div>)}</aside><section>{active?<>
      <header className="training-course-header"><div><span>{label(active.domain)}</span><h2>{active.title}</h2><p>{active.description}</p></div>{myEnrollment?<b>{myEnrollment.status==='qualified'?pick('Completed','הושלם'):pick('Assigned','הוקצה')}</b>:null}{canEdit&&!selected.startsWith("67402026-1002-")?<div className="training-course-actions"><button onClick={()=>editCourse(active)}>{pick("Edit","עריכה")}</button><button onClick={()=>void archiveCourse(active)}>{pick("Archive","ארכיון")}</button>{canDelete?<button className="danger" onClick={()=>void deleteCourse(active)}>{pick("Delete","מחיקה")}</button>:null}</div>:null}</header>
      <CourseResourceShelf pick={pick} courseId={active.id}/>
      {selected.startsWith("67402026-1002-")&&<div className="academy-preview-note"><p>{pick("Prepared practical course: lesson, quiz and two demonstrations. Assign it below or open the guided course.","קורס מעשי מוכן: שיעור, מבחן ושתי הדגמות. ניתן להקצות אותו בהמשך או לפתוח את הקורס המודרך.")}</p><button onClick={()=>openCourse(selected)}>{pick("Open guided course","פתיחת הקורס המודרך")}</button></div>}
      {canEdit?<div className="training-admin-tools">{!selected.startsWith("67402026-1002-")&&<form onSubmit={saveModule}><strong>{pick(editingModule?"Edit module":"Add module",editingModule?"עריכת יחידה":"הוספת יחידה")}</strong><input required value={authorText(moduleTitle,language)} onChange={e=>setModuleTitle(updateAuthorText(moduleTitle,e.target.value,language))} placeholder={pick("Module title","שם יחידה")}/><textarea required value={authorText(instructions,language)} onChange={e=>setInstructions(updateAuthorText(instructions,e.target.value,language))} placeholder={pick("Instructions, completion criteria and resource links","הוראות, קריטריוני השלמה וקישורים למשאבים")}/><span><button>{pick(editingModule?"Save module":"Add module",editingModule?"שמירת יחידה":"הוספת יחידה")}</button>{editingModule?<button type="button" onClick={()=>{setEditingModule(null);setModuleTitle("");setInstructions("");}}>{pick("Cancel","ביטול")}</button>:null}</span></form>}<div className="training-assignment-panel"><strong>{pick("Assign this course","הקצאת הקורס")}</strong><div className="assignment-mode">{(["all","subteam","members"] as const).map(mode=><button type="button" className={assignmentMode===mode?"is-active":""} onClick={()=>setAssignmentMode(mode)} key={mode}>{mode==="all"?pick("Whole team","כל הקבוצה"):mode==="subteam"?pick("Subteam","תת־צוות"):pick("Select members","בחירת חברים")}</button>)}</div>{assignmentMode==="all"?<p>{pick(`All ${people.length} active members will receive this course.`,`כל ${people.length} החברים הפעילים יקבלו את הקורס.`)}</p>:assignmentMode==="subteam"?<select value={assignSubteam} onChange={e=>setAssignSubteam(e.target.value)}><option value="">{pick("Choose subteam…","בחירת תת־צוות…")}</option>{Array.from(new Set(people.flatMap(memberTeams))).sort().map(x=><option key={x} value={x}>{label(x)}</option>)}</select>:<div className="member-multiselect">{people.map(x=><label key={x.id}><input type="checkbox" checked={assignMembers.includes(x.id)} onChange={()=>toggleMember(x.id)}/><span><strong>{x.display_name}</strong><small>{memberTeams(x).join(" · ")||pick("No subteam","ללא תת־צוות")}</small></span></label>)}</div>}<label>{pick("Due date (optional)","תאריך יעד (אופציונלי)")}<input type="date" value={assignDue} onChange={e=>setAssignDue(e.target.value)}/></label><button type="button" onClick={()=>void enroll()}>{pick("Assign course","הקצאת קורס")}</button></div></div>:null}
      <ol className="training-modules">{courseModules.map((m,i)=>{const item=myEnrollment?evidence.find(x=>x.enrollment_id===myEnrollment.id&&x.module_id===m.id):null;return <li key={m.id}><b>{i+1}</b><div><header><h3>{text(m.title)}</h3>{canEdit?<span><button onClick={()=>{setEditingModule(m.id);setModuleTitle(m.title);setInstructions(m.instructions);}}>{pick("Edit","עריכה")}</button>{canDelete?<button className="danger" onClick={()=>void deleteModule(m)}>{pick("Delete","מחיקה")}</button>:null}</span>:null}</header><LinkedText text={text(m.instructions)}/>{item?<div className={`training-submission status-${item.status}`}><strong>{label(item.status)}</strong><p>{item.note}</p>{item.review_note?<small>{item.review_note}</small>:null}{instructor&&!studentPreview&&canReview&&item.status==="submitted"?<span><button onClick={()=>void review(item,"approved")}>{pick("Approve","אישור")}</button><button onClick={()=>void review(item,"changes_requested")}>{pick("Request changes","בקשת שינוי")}</button></span>:null}</div>:myEnrollment&&!studentPreview?<form onSubmit={e=>{e.preventDefault();void submit(myEnrollment,m);}}><textarea required value={note[m.id]??""} onChange={e=>setNote({...note,[m.id]:e.target.value})} placeholder={pick("Describe or link your evidence.","תארו או קשרו את הראיה.")}/><button>{pick("Submit evidence","הגשת ראיה")}</button></form>:<small>{pick("This course has not been assigned to you.","קורס זה לא הוקצה לכם.")}</small>}</div></li>})}</ol>
    </>:null}</section></div></>:null}

    {academyView==="assessments"&&isOfficial&&<OfficialTraining {...officialProps} mode="detail" selected={selected}/>}
    {academyView==="assessments"&&!isOfficial?<section className="academy-assessment-workspace">
      <header><div><span>{active?.domain?label(active.domain):null}</span><h2>{active?.title??pick("Choose a course","בחירת קורס")}</h2><p>{pick("Practice, demonstrate and test real FRC capability.","תרגול, הדגמה ובחינה של יכולת FRC אמיתית.")}</p></div><label>{pick("Course","קורס")}<select value={selected} onChange={e=>setSelected(e.target.value)}>{courses.map(item=><option value={item.id} key={item.id}>{item.title}</option>)}</select></label></header>
      {canEdit&&active?<section className="assessment-audience"><header><div><strong>{pick("Who receives this activity?","מי יקבל את הפעילות?")}</strong><small>{pick("The selected members are enrolled in the course and receive a notification and Home responsibility.","החברים שנבחרו נרשמים לקורס ומקבלים התראה ומשימה בדף הבית.")}</small></div><b>{assessmentForm.target_type==="all"?people.length:assessmentForm.target_type==="subteams"?people.filter(person=>memberTeams(person).some(team=>assessmentForm.target_values.some(value=>normalizedTeamMatch(team,value)))).length:assessmentForm.target_values.length} {pick("recipients","נמענים")}</b></header><div className="assignment-mode">{(["all","subteams","members"] as const).map(mode=><button type="button" className={assessmentForm.target_type===mode?"is-active":""} onClick={()=>setAssessmentForm({...assessmentForm,target_type:mode,target_values:[]})} key={mode}>{mode==="all"?pick("Whole team","כל הקבוצה"):mode==="subteams"?pick("Select teams","בחירת צוותים"):pick("Select people","בחירת אנשים")}</button>)}</div>{assessmentForm.target_type==="subteams"?<div className="audience-chip-grid">{Array.from(new Set(people.flatMap(memberTeams))).sort().map(team=><label key={team}><input type="checkbox" checked={assessmentForm.target_values.includes(team)} onChange={()=>setAssessmentForm({...assessmentForm,target_values:assessmentForm.target_values.includes(team)?assessmentForm.target_values.filter(value=>value!==team):[...assessmentForm.target_values,team]})}/><span>{team}</span></label>)}</div>:assessmentForm.target_type==="members"?<div className="member-multiselect">{people.map(person=><label key={person.id}><input type="checkbox" checked={assessmentForm.target_values.includes(person.id)} onChange={()=>setAssessmentForm({...assessmentForm,target_values:assessmentForm.target_values.includes(person.id)?assessmentForm.target_values.filter(value=>value!==person.id):[...assessmentForm.target_values,person.id]})}/><span><strong>{person.display_name}</strong><small>{memberTeams(person).join(" · ")||pick("No team","ללא צוות")}</small></span></label>)}</div>:<p>{pick(`All ${people.length} active members will receive this activity.`,`כל ${people.length} החברים הפעילים יקבלו את הפעילות.`)}</p>}</section>:null}
      {canEdit&&active&&!selected.startsWith("67402026-1002-")?<form className="academy-assessment-form" onSubmit={saveAssessment}><div><strong>{pick(editingAssessment?"Edit learning activity":"Create a learning activity",editingAssessment?"עריכת פעילות למידה":"יצירת פעילות למידה")}</strong><small>{pick("Assignments, secure quizzes, practical checks or reflection","מטלות, מבחנים מאובטחים, בדיקות מעשיות או רפלקציה")}</small></div><label>{pick("Title","כותרת")}<input required value={authorText(assessmentForm.title,language)} onChange={e=>setAssessmentForm({...assessmentForm,title:updateAuthorText(assessmentForm.title,e.target.value,language)})}/></label><label>{pick("Type","סוג")}<select value={assessmentForm.assessment_type} onChange={e=>setAssessmentForm({...assessmentForm,assessment_type:e.target.value as Assessment["assessment_type"]})}>{["assignment","quiz","practical","reflection"].map(type=><option key={type}>{type}</option>)}</select></label>{assessmentForm.assessment_type==="reflection"?<p className="wide assessment-type-help">{pick("Reflection asks a student to explain what they learned, what was difficult, and what they would improve. It is reviewed as feedback, not a right-or-wrong test.","רפלקציה מבקשת מהתלמיד/ה להסביר מה למדו, מה היה קשה ומה היו משפרים. היא נבדקת כמשוב ולא כמבחן של נכון או לא נכון.")}</p>:null}<label className="wide">{pick("Instructions and success criteria","הוראות וקריטריוני הצלחה")}<textarea required rows={3} value={authorText(assessmentForm.instructions,language)} onChange={e=>setAssessmentForm({...assessmentForm,instructions:updateAuthorText(assessmentForm.instructions,e.target.value,language)})}/></label>{assessmentForm.assessment_type==="quiz"?<div className="wide quiz-builder"><header><div><strong>{pick("Quiz questions","שאלות המבחן")}</strong><small>{pick("Choose single answer, multiple answers, or written response. Correct answers stay private.","בחרו תשובה אחת, מספר תשובות או תשובה כתובה. התשובות הנכונות נשארות פרטיות.")}</small></div><button type="button" onClick={addQuizQuestion}>+ {pick("Add question","הוספת שאלה")}</button></header>{quizQuestions.map((question,index)=><fieldset key={question.id}><legend>{pick(`Question ${index+1}`,`שאלה ${index+1}`)}</legend><label>{pick("Question","שאלה")}<input required value={question.prompt} onChange={e=>patchQuizQuestion(index,{prompt:e.target.value})}/></label><label>{pick("Answer type","סוג תשובה")}<select value={question.kind} onChange={e=>patchQuizQuestion(index,{kind:e.target.value as QuizQuestion["kind"],correct_answers:[]})}><option value="single_choice">{pick("One correct answer","תשובה נכונה אחת")}</option><option value="multiple_choice">{pick("Multiple correct answers","מספר תשובות נכונות")}</option><option value="written">{pick("Written answer","תשובה כתובה")}</option></select></label>{question.kind!=="written"?<div className="quiz-options">{question.options.map((option,optionIndex)=><label key={optionIndex}><input type={question.kind==="single_choice"?"radio":"checkbox"} name={`correct-${question.id}`} checked={!!option&&question.correct_answers.includes(option)} onChange={()=>toggleCorrectAnswer(index,option)}/><input required={optionIndex<2} placeholder={pick(`Answer ${optionIndex+1}`,`תשובה ${optionIndex+1}`)} value={option} onChange={e=>{const options=[...question.options];const old=options[optionIndex];options[optionIndex]=e.target.value;patchQuizQuestion(index,{options,correct_answers:question.correct_answers.map(value=>value===old?e.target.value:value)});}}/></label>)}</div>:<label className="wide">{pick("Private answer guide for reviewer (optional)","מדריך תשובה פרטי לבודק/ת (אופציונלי)")}<textarea rows={2} value={question.correct_answers[0]??""} onChange={e=>patchQuizQuestion(index,{correct_answers:e.target.value?[e.target.value]:[]})}/></label>}<label>{pick("Points","נקודות")}<input type="number" min="1" value={question.points} onChange={e=>patchQuizQuestion(index,{points:Number(e.target.value)})}/></label>{quizQuestions.length>1?<button type="button" className="secondary quiz-remove" onClick={()=>setQuizQuestions(current=>current.filter((_,itemIndex)=>itemIndex!==index))}>{pick("Remove question","הסרת שאלה")}</button>:null}</fieldset>)}<div className="quiz-total"><span>{pick("Calculated maximum","ציון מרבי מחושב")}</span><strong>{quizTotal}</strong></div></div>:<label className="wide">{pick("Prompts — one per line (optional)","שאלות מנחות — אחת בכל שורה (אופציונלי)")}<textarea rows={4} value={assessmentForm.questions} onChange={e=>setAssessmentForm({...assessmentForm,questions:e.target.value})}/></label>}<div className="wide assessment-settings"><label className="checkbox-label"><input type="checkbox" checked={assessmentForm.required} onChange={e=>setAssessmentForm({...assessmentForm,required:e.target.checked})}/><span><strong>{pick("Required","חובה")}</strong><small>{pick("Members must complete this activity","החברים חייבים להשלים את הפעילות")}</small></span></label><label className="checkbox-label"><input type="checkbox" checked={assessmentForm.graded} onChange={e=>setAssessmentForm({...assessmentForm,graded:e.target.checked})}/><span><strong>{pick("Use a score","שימוש בציון")}</strong><small>{pick("Choice questions grade automatically; written answers go to review","שאלות בחירה נבדקות אוטומטית; תשובות כתובות עוברות לבדיקה")}</small></span></label></div><label>{pick("Due date (optional)","תאריך יעד (אופציונלי)")}<input type="datetime-local" value={assessmentForm.due_at} onChange={e=>setAssessmentForm({...assessmentForm,due_at:e.target.value})}/></label><label>{pick("Allowed attempts","מספר ניסיונות")}<select value={assessmentForm.max_attempts} onChange={e=>setAssessmentForm({...assessmentForm,max_attempts:e.target.value})}>{[1,2,3,4,5].map(value=><option value={value} key={value}>{value}</option>)}</select></label>{assessmentForm.graded?<><label>{pick("Maximum score","ציון מרבי")}<input required type="number" min="1" disabled={assessmentForm.assessment_type==="quiz"} value={assessmentForm.assessment_type==="quiz"?quizTotal:assessmentForm.max_score} onChange={e=>setAssessmentForm({...assessmentForm,max_score:e.target.value})}/></label><label>{pick("Passing score","ציון עובר")}<input type="number" min="0" max={assessmentForm.assessment_type==="quiz"?quizTotal:assessmentForm.max_score||undefined} value={assessmentForm.passing_score} onChange={e=>setAssessmentForm({...assessmentForm,passing_score:e.target.value})}/></label></>:null}<div className="wide academy-form-actions"><button>{pick(editingAssessment?"Save activity":"Add activity",editingAssessment?"שמירת הפעילות":"הוספת פעילות")}</button>{editingAssessment?<button type="button" className="secondary" onClick={resetAssessmentForm}>{pick("Cancel","ביטול")}</button>:null}</div></form>:null}
      <div className="academy-assessment-list">{selected.startsWith("67402026-1002-")?<div className="academy-empty"><h3>{pick("Guided practical course","קורס מעשי מודרך")}</h3><p>{pick("Learn, answer the quiz, submit demonstrations and review their criteria in one flow.","למדו, ענו למבחן, הגישו הדגמות ובדקו קריטריונים בתהליך אחד.")}</p><button onClick={()=>setAcademyView("practical")}>{pick("Open guided learning","פתיחת למידה מודרכת")}</button></div>:courseAssessments.length?courseAssessments.map(item=>{const credit=officialCredits.find(c=>c.assessment_id===item.id&&c.member_id===profile?.id);if(credit)return <article key={item.id} className="academy-assessment-card"><h3>{text(item.title)}</h3><p>{pick("Satisfied by verified official training. No repeat quiz or fabricated score.","הדרישה מולאה באמצעות הכשרה רשמית מאומתת. אין מבחן חוזר או ציון מלאכותי.")}</p><button onClick={()=>leaveInstructor("progress")}>{pick("View certificate","צפייה בתעודה")}</button></article>;const submissions=assessmentSubmissions.filter(row=>row.assessment_id===item.id&&row.member_id===profile?.id),submission=submissions[0],draft=draftFor(item),attemptsLeft=Math.max(0,(item.max_attempts??1)-submissions.length),locked=studentPreview||submission?.status==="submitted"||attemptsLeft===0;return <article key={item.id} className={`academy-assessment-card status-${submission?.status??"not-started"}`}><header><span>{label(item.assessment_type)}</span><div>{item.required?<b>{pick("Required","חובה")}</b>:null}{item.graded?<b>{item.max_score} {pick("points","נקודות")}</b>:<b>{pick("Feedback only","משוב בלבד")}</b>}</div></header><h3>{text(item.title)}</h3><div className="assessment-meta">{item.due_at?<span>{pick("Due","עד")}: {new Date(item.due_at).toLocaleString()}</span>:null}<span>{pick("Attempts","ניסיונות")}: {submissions.length}/{item.max_attempts??1}</span></div><LinkedText text={text(item.instructions)}/>{item.questions?.length?<ol>{item.questions.map((question,index)=>{const structured=typeof question!=="string"?question:null,prompt=structured?.prompt??question,key=structured?.id??String(index),value=draft.answers[key];return <li key={`${item.id}-${key}`}><fieldset className="student-quiz-question"><legend>{text(String(prompt))}</legend>{structured?.kind==="single_choice"?<div className="student-quiz-options">{structured.options.map(option=><label key={option}><input type="radio" name={`${item.id}-${key}`} value={option} checked={value===option} disabled={locked} onChange={e=>setSubmissionDrafts({...submissionDrafts,[item.id]:{...draft,answers:{...draft.answers,[key]:e.target.value}}})}/><span>{text(option)}</span></label>)}</div>:structured?.kind==="multiple_choice"?<div className="student-quiz-options">{structured.options.map(option=>{const selected=Array.isArray(value)&&value.includes(option);return <label key={option}><input type="checkbox" value={option} checked={selected} disabled={locked} onChange={()=>{const next=structured.options.filter(candidate=>candidate===option?!selected:Array.isArray(value)&&value.includes(candidate));setSubmissionDrafts({...submissionDrafts,[item.id]:{...draft,answers:{...draft.answers,[key]:next}}});}}/><span>{text(option)}</span></label>})}</div>:<textarea value={typeof value==="string"?value:""} disabled={locked} onChange={e=>setSubmissionDrafts({...submissionDrafts,[item.id]:{...draft,answers:{...draft.answers,[key]:e.target.value}}})}/>}</fieldset></li>})}</ol>:null}{myEnrollment?<div className="academy-student-response">{item.assessment_type!=="quiz"?<><label>{pick("Your response or evidence","התשובה או הראיה שלך")}<textarea rows={3} value={draft.response} disabled={locked} onChange={e=>setSubmissionDrafts({...submissionDrafts,[item.id]:{...draft,response:e.target.value}})}/></label><label>{pick("Evidence link (optional)","קישור לראיה (אופציונלי)")}<input type="url" value={draft.resource_url} disabled={locked} onChange={e=>setSubmissionDrafts({...submissionDrafts,[item.id]:{...draft,resource_url:e.target.value}})}/></label></>:null}{submission?<div className="academy-result"><b>{label(submission.status)}</b>{submission.score!=null?<strong>{submission.score}/{item.max_score}</strong>:null}{submission.feedback?<p>{academyFeedback(submission.feedback,pick)}</p>:null}</div>:null}{!locked&&attemptsLeft>0?<button onClick={()=>void submitAssessment(item)}>{submission?.status==="changes_requested"?pick("Try again","ניסיון נוסף"):pick(item.assessment_type==="quiz"?"Submit answers":"Submit for review",item.assessment_type==="quiz"?"שליחת תשובות":"שליחה לבדיקה")}</button>:attemptsLeft===0?<div className="academy-attempt-limit">{pick("No attempts remaining","לא נותרו ניסיונות")}</div>:null}</div>:<div className="academy-not-assigned">{pick("Assign this course before the student can submit work.","יש להקצות את הקורס לפני שניתן להגיש עבודה.")}</div>}{canEdit?<footer><button onClick={()=>editAssessment(item)}>{pick("Edit","עריכה")}</button><button onClick={()=>void archiveAssessment(item)}>{pick("Archive","ארכיון")}</button></footer>:null}</article>}):<div className="academy-empty"><strong>{pick("No assignments or tests yet","אין עדיין מטלות או מבחנים")}</strong><p>{pick("Create the first focused learning activity for this course.","צרו את פעילות הלמידה הממוקדת הראשונה לקורס זה.")}</p></div>}</div>
    </section>:null}

    {academyView==="practical"?<Suspense fallback={<p>Loading…</p>}><PracticalLearning initialCourse={selected} initialStep={practicalStep} onStep={setPracticalStep} reviewSubmission={reviewSubmission} hideCourseList={!!selected} previewOnly={studentPreview} onCourse={id=>{setSelected(id);setInstructor(canCreate);setAcademyView("content");}} onLab={(id,area)=>{setSelected(id);setLabCourse(id);navigation.set("area",area??"all");navigation.set("robot","darwin");setAcademyView("robot-lab");}}/></Suspense>:null}
    {academyView==="robot-tests"?<Suspense fallback={<p>Loading…</p>}><RobotTestWorkbench/></Suspense>:null}
    {academyView==="robot-lab"?<Suspense fallback={<p>Loading…</p>}><RobotLearningLab pick={pick} initialRobot={searchParams.get('robot')==='limestone'?'limestone':'darwin'} initialArea={(['electrical','power','can','network','intake','shooter','hopper','drive'].includes(searchParams.get('area')??'')?searchParams.get('area'):'all') as StudyArea} draftScope={`${profile?.id??'anonymous'}:${labCourse}:${studentPreview?'preview':'learning'}`} targets={assessments.filter(a=>a.course_id===labCourse&&a.assessment_type==='practical').map(a=>({id:a.id,title:text(a.title)}))} onEvidence={!studentPreview&&labCourse.startsWith('67402026-1002-')?async (observation,target)=>{
      if(!profile)return false;
      const [prior,pack]=await Promise.all([supabase.from('training_lesson_drafts').select('draft,updated_at').eq('course_id',labCourse).eq('member_id',profile.id).maybeSingle(),supabase.from('training_lesson_packs').select('content').eq('course_id',labCourse).single()]);
      if(prior.error||pack.error){setMessage(prior.error?.message??pack.error?.message??'');return false;}
      const index=(pack.data?.content?.practicalIds??[]).indexOf(target);if(index<0)return false;
      const key=draftKey(profile.id,labCourse),recovered=readRecovery<any>(key);const draft=recovered&&recovered.updatedAt>(prior.data?.updated_at??'')?recovered.value:prior.data?.draft??{answers:{},responses:['',''],urls:['','']};
      const responses=[...(draft.responses??['',''])];responses[index]=[responses[index],observation].filter(Boolean).join('\n\n');
      const saved=await supabase.from('training_lesson_drafts').upsert({course_id:labCourse,member_id:profile.id,draft:{...draft,responses,step:2},updated_at:new Date().toISOString()});
      if(saved.error){setMessage(saved.error.message);return false;}clearRecovery(key);setSelected(labCourse);setPracticalStep(2);setAcademyView('practical');return true;
    }:undefined}/></Suspense>:null}
    {academyView==="catalog"&&instructor&&active&&<div className="academy-context-bar"><strong>{active.title}</strong><button onClick={()=>setAcademyView("content")}>{pick("Return to course","חזרה לקורס")}</button></div>}
    {academyView==="catalog"?<SkillsResourceCatalog pick={pick} courses={courses} selectedCourse={selected} onSelectCourse={setSelected} canChooseCourse={instructor&&canCreate} canAttach={canEdit&&Boolean(selected)} isAdmin={profile?.role==="admin"}/>:null}

    {academyView==="review"&&canReview&&<OfficialTraining {...officialProps} mode="review" selected={reviewCourse||undefined}/>}
    {academyView==="review"&&canReview?<section className="academy-review-workspace"><header><div><span>{pick("Instructor workspace","מרחב מדריכים")}</span><h2>{pick("Review queue","תור לבדיקה")}</h2><p>{pick("One place for submitted work, feedback and optional scores.","מקום אחד לעבודות שהוגשו, משוב וציונים אופציונליים.")}</p></div><label>{pick("Course","קורס")}<select value={reviewCourse} onChange={e=>setReviewCourse(e.target.value)}><option value="">{pick("All permitted courses","כל הקורסים המורשים")}</option>{courses.map(item=><option value={item.id} key={item.id}>{item.title}</option>)}</select></label></header><div className="academy-review-list">{moduleReviewQueue.map(item=><article key={item.id}><h3>{text(modules.find(m=>m.id===item.module_id)?.title)}</h3><strong>{people.find(p=>p.id===item.member_id)?.display_name}</strong><p>{item.note}</p><footer><button onClick={()=>void review(item,"approved")}>{pick("Approve evidence","אישור ראיה")}</button><button onClick={()=>void review(item,"changes_requested")}>{pick("Request changes","בקשת תיקון")}</button></footer></article>)}{reviewQueue.length?reviewQueue.map(item=>{const assessment=assessments.find(row=>row.id===item.assessment_id),person=people.find(row=>row.id===item.member_id);return <article key={item.id}><header><div><strong>{person?.display_name??pick("Member","חבר/ה")}</strong><span>{text(assessment?.title)}</span></div><b>{label(item.status)}</b></header>{item.response?<p>{item.response}</p>:null}{Object.values(item.answers??{}).map((answer,index)=><blockquote key={index}>{Array.isArray(answer)?answer.map(text).join(" · "):text(answer)}</blockquote>)}{item.resource_url?<a href={item.resource_url} target="_blank" rel="noreferrer">{pick("Open submitted evidence","פתיחת הראיה שהוגשה")} ↗</a>:null}<footer><button onClick={()=>void reviewAssessment(item,"reviewed")}>{pick(item.assessment_id.startsWith("67402026-1002-")?"Open evidence & rubric":"Approve / grade",item.assessment_id.startsWith("67402026-1002-")?"פתיחת ראיות וקריטריונים":"אישור / ציון")}</button><button className="secondary" onClick={()=>void reviewAssessment(item,"changes_requested")}>{pick("Request changes","בקשת תיקון")}</button></footer></article>}):moduleReviewQueue.length?null:<div className="academy-empty"><strong>{pick("Review queue is clear","תור הבדיקה ריק")}</strong><p>{pick("New student submissions will appear here.","הגשות חדשות של תלמידים יופיעו כאן.")}</p></div>}</div></section>:null}
    {academyView==="progress"&&<OfficialTraining {...officialProps} mode="progress"/>}
    {academyView==="progress"?<SkillsGradebook credits={officialCredits} pick={pick} profileId={profile?.id} canReview={instructor&&canReview} courses={courses} modules={modules} enrollments={learningEnrollments} evidence={evidence} assessments={publicAssessments} submissions={assessmentSubmissions} people={people} progressEvents={progressEvents}/>:null}
  </main>;
}
